#!/usr/bin/env python3
"""
==========================================================================
 CARTOON SHORT FACTORY  --  complete repository in ONE self-extracting file
==========================================================================

INSTRUCTIONS FOR CHATGPT (or any AI / person that receives this file)
---------------------------------------------------------------------
This single file CONTAINS the entire "cartoon-short-factory" skill/repository
(every source file, doc, example and reference image), compressed and base64
encoded at the bottom. Do NOT try to retype, summarise or "recreate" it.
Do NOT edit the encoded payload. Just RUN this file:

    python3 cartoon_short_factory_bundle.py --out ./repo

(In ChatGPT's code tool: run the file with --out /mnt/data/repo, then also
 pass --zip so it writes cartoon-short-factory.zip, and give the user the
 zip as the download.)

What it does:
  1. Decodes the payload and verifies its SHA-256 (aborts if corrupted).
  2. Writes the repo to <out>/cartoon-short-factory/  (126 files).
  3. Adds a root README.md and .gitignore (those are the only added files).
  4. --git   : also runs `git init` and makes a first commit (if git exists).
  5. --zip   : also writes <out>/cartoon-short-factory.zip.
  6. --list  : prints the file list without writing anything.

WHAT THIS REPOSITORY IS (so you understand it, not to rebuild it)
-----------------------------------------------------------------
A skill ("SKILL.md" is the entry point, read it first) for making vertical
30-70 s cartoon-3D story shorts entirely from code: 2D-style rigged characters
in a colourful, ink-outlined 3D world. Pipeline:
  topic+facts -> SCRIPT.md (linted) -> British TTS voice (kokoro-onnx) ->
  story.json -> three.js + cannon-es headless-Chrome renderer -> ffmpeg ->
  synthesized SFX/music mix -> automated QA ("PHYSICS AUDIT").
Layout:
  SKILL.md        the skill: rules, pipeline, story.json reference, gotchas
  factory/        chat-friendly toolkit (render/ = three.js renderer,
                  library/ = 25 character presets, tools/ = linter, TTS,
                  timing checks, sound + story generators, docs/ = RULES.md)
  references/     STYLE_BIBLE.md, measured look reports, reference frames/sheets
  templates/      original Remotion "high-end route" source + audio DSP/SFX/music
  examples/       3 finished scripts + story.json (millennium, queue, pisa)
To use it as intended: follow SKILL.md "Setup" then "Pipeline". Requirements:
Node + npm, Python 3, ffmpeg, Chrome/Chromium (software WebGL is enough).

Bundle SHA-256 (of the zip payload): 3beb8e0b6b9353f95ec90d4ba6b14b46eba7bd2bdbc1aae4bbf8fec1a5075d59
"""
import argparse, base64, hashlib, io, os, subprocess, sys, zipfile

SHA256 = "3beb8e0b6b9353f95ec90d4ba6b14b46eba7bd2bdbc1aae4bbf8fec1a5075d59"

README = """# Cartoon Short Factory

Code-rendered vertical cartoon-3D story shorts (script -> voice -> three.js render -> sound -> QA).
Start with `cartoon-short-factory/SKILL.md`.

Quick start (from the repo root):

    cd cartoon-short-factory
    cp -r factory ~/shorts-factory && cd ~/shorts-factory/render && npm i
    pip install kokoro-onnx soundfile numpy
    node render.mjs story.example.json out.mp4

Needs Node, Python 3, ffmpeg and Chrome/Chromium. See `factory/docs/CHAT_MODE.md` and `factory/docs/RULES.md`.
Licence: see `cartoon-short-factory/LICENSE`.
"""

GITIGNORE = """node_modules/
__pycache__/
*.pyc
out/
voice/
*.mp4
*.wav
.DS_Store
"""

def load_zip():
    marker = "PAYLOAD" + "_BEGIN"
    with open(os.path.abspath(__file__), "r", encoding="utf-8") as f:
        text = f.read()
    start = text.rindex("\n# " + marker + "\n") + len(marker) + 4
    b64 = "".join(line[2:] if line.startswith("# ") else line
                  for line in text[start:].splitlines())
    raw = base64.b64decode(b64)
    if hashlib.sha256(raw).hexdigest() != SHA256:
        sys.exit("ERROR: payload checksum mismatch - the file was altered or truncated. Re-download it.")
    return raw

def main():
    ap = argparse.ArgumentParser(description="Extract the cartoon-short-factory repository.")
    ap.add_argument("--out", default="./repo", help="output directory (default ./repo)")
    ap.add_argument("--git", action="store_true", help="git init + first commit")
    ap.add_argument("--zip", action="store_true", help="also write cartoon-short-factory.zip")
    ap.add_argument("--list", action="store_true", help="list files only")
    a = ap.parse_args()
    raw = load_zip()
    z = zipfile.ZipFile(io.BytesIO(raw))
    if a.list:
        print("\n".join(z.namelist())); return
    os.makedirs(a.out, exist_ok=True)
    z.extractall(a.out)
    with open(os.path.join(a.out, "README.md"), "w") as f: f.write(README)
    with open(os.path.join(a.out, ".gitignore"), "w") as f: f.write(GITIGNORE)
    n = len(z.namelist())
    print(f"OK: {n} files extracted to {os.path.abspath(a.out)}/cartoon-short-factory (checksum verified)")
    if a.git:
        try:
            subprocess.run(["git", "init", "-q"], cwd=a.out, check=True)
            subprocess.run(["git", "add", "-A"], cwd=a.out, check=True)
            subprocess.run(["git", "-c", "user.name=bundle", "-c", "user.email=bundle@local",
                            "commit", "-q", "-m", "Import cartoon-short-factory"], cwd=a.out, check=True)
            print("git repository initialised with first commit")
        except Exception as e:
            print("git step skipped:", e)
    if a.zip:
        zp = os.path.join(a.out, "cartoon-short-factory.zip")
        with zipfile.ZipFile(zp, "w", zipfile.ZIP_DEFLATED) as zz:
            for root, dirs, files in os.walk(a.out):
                dirs[:] = [d for d in dirs if d != ".git"]
                for fn in files:
                    p = os.path.join(root, fn)
                    if p == zp: continue
                    zz.write(p, os.path.relpath(p, a.out))
        print("zip written:", zp)

if __name__ == "__main__":
    main()

